#define MENU_FONT_COUNT ((int)(sizeof(g_menu_font) / sizeof(g_menu_font[0])))

/* 线性查找码点对应的点阵；找不到返回 NULL。 */
static inline const uint8_t *menu_glyph_bits(uint32_t cp)
{
    for (int i = 0; i < MENU_FONT_COUNT; i++) {
        if (g_menu_font[i].cp == cp) return g_menu_font[i].bits;
    }
    return NULL;
}

